package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "TDES", "RC2", "RC4", "Blowfish"}
weak_block_modes := {"ECB"}
weak_hash_functions := {"MD5", "SHA1", "SHA-1"}
deprecated_tls_versions := {"TLSv1.0", "TLSv1.1", "TLS1.0", "TLS1.1", "SSLv2", "SSLv3"}

key_size_fields := {"key_size", "key_length", "key_bits", "rsa_key_size", "key_size_in_bits", "minimum_key_size", "key_spec"}

signature_algorithms := {"sha1WithRSAEncryption", "md5WithRSA", "SHA1-RSA", "DSA-SHA1"}

encryption_disable_values := {"none", "null", "disabled", "false"}
weak_cipher_keywords := {"NULL", "EXPORT", "DES", "RC4", "3DES"}

check_weak_algorithm(value) {
    value.ir_type == "String"
    upper_value := upper(value.value)
    weak_algorithms[upper_value]
} else {
    value.ir_type == "Hash"
    some k
    v := value.value[k]
    v.ir_type == "String"
    upper_val := upper(v.value)
    weak_algorithms[upper_val]
}

check_weak_block_mode(value) {
    value.ir_type == "String"
    upper_value := upper(value.value)
    weak_block_modes[upper_value]
}

check_weak_hash(value) {
    value.ir_type == "String"
    upper_value := upper(value.value)
    weak_hash_functions[upper_value]
}

check_deprecated_tls(value) {
    value.ir_type == "String"
    upper_value := upper(replace(value.value, ".", ""))
    deprecated_tls_versions[upper_value]
}

check_weak_signature(value) {
    value.ir_type == "String"
    signature_algorithms[value.value]
}

is_insufficient_key_size(attr_name, value) {
    key_size_fields[lower(attr_name)]
    value.ir_type == "Integer"
    value.value < 2048
}

is_encryption_disabled(attr_name, value) {
    encryption_keywords := {"encrypted", "encryption", "enable_encryption", "storage_encrypted", "encryption_at_rest", "sse_enabled", "tls_enabled", "ssl_enabled", "require_ssl", "ssl_enforcement"}
    encryption_keywords[lower(attr_name)]
    value.ir_type == "String"
    lower_val := lower(value.value)
    lower_val == encryption_disable_values[_]
} else {
    encryption_keywords := {"encrypted", "encryption", "enable_encryption", "storage_encrypted", "encryption_at_rest", "sse_enabled", "tls_enabled", "ssl_enabled", "require_ssl", "ssl_enforcement"}
    encryption_keywords[lower(attr_name)]
    value.ir_type == "Boolean"
    value.value == false
}

contains_weak_cipher(value) {
    value.ir_type == "String"
    some keyword
    keyword := weak_cipher_keywords[_]
    regex.match(sprintf("(?i).*%s.*", [keyword]), value.value)
} else {
    value.ir_type == "Array"
    some elem
    elem := value.value[_]
    elem.ir_type == "String"
    contains_weak_cipher(elem)
}

check_encoding_as_encryption(value) {
    value.ir_type == "String"
    encodings := {"base64", "rot13", "urlencode", "hex"}
    lower_val := lower(value.value)
    encodings[lower_val]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated encryption algorithm. (CWE-326)"
    }
}

